ee:message.ee:set-payload:
%dw 2.0 output application/java
var r=payload.items[0]
--- {owner:r.owner.login as String default "",repoName:r.name as String default "",defaultBranch:r.default_branch as String default "main",htmlUrl:r.html_url as String default ""}

%dw 2.0 output application/json
---
{
    success: true,
    message: "GitHub repository SAP setup completed successfully.",
    repository: { owner:vars.repoOwner, name:vars.repoNameClean, url:vars.repoHtmlUrl, defaultBranch:vars.defaultBranch },
    featureBranch: { name:p('feature.branch.name'), baseSha:vars.baseSha },
    pomXmlChanges: {
        committed: true,
        sha: vars.pomCommitSha,
        dependencyAdded: "com.mulesoft.connectors:mule-sap-connector:4.3.0"
    },
    globalXmlChanges: {
        found: (vars.gxFound default false),
        upgraded: (vars.gxFound default false),
        description: if (vars.gxFound default false) "SAP config upgraded to Message Server format with Extended Properties (jco.client.mshost, msserv, group, saprouter)" else "global.xml not found at src/main/mule/global.xml - SAP config upgrade skipped"
    }
}
